        <h1><?= $section === 'users' ? 'Utilizadores' : ($section === 'groups' ? 'Grupos' : 'Permissões') ?></h1>
        <p><?= $section === 'users' ? 'Crie utilizadores e associe-os aos grupos de acesso.' : ($section === 'groups' ? 'Crie e organize grupos de acesso.' : 'Defina as ações permitidas para cada grupo.') ?></p>
    </header>
    <?php if ($section === 'users'): ?>
    <div class="row g-4">
        <div class="col-12 col-xl-6"><article class="card"><div class="card-header"><?= $user ? 'Editar utilizador' : 'Novo utilizador' ?></div><div class="card-body"><form method="post" action="index.php?class=AccessManagement&amp;method=onSaveUser"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($data['csrf'], ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) ($user->id ?? 0) ?>"><label class="form-label">Nome</label><input class="form-control mb-3" name="nome" required value="<?= htmlspecialchars((string) ($user->nome ?? ''), ENT_QUOTES, 'UTF-8') ?>"><label class="form-label">E-mail</label><input class="form-control mb-3" type="email" name="email" required value="<?= htmlspecialchars((string) ($user->email ?? ''), ENT_QUOTES, 'UTF-8') ?>"><label class="form-label">Palavra-passe<?= $user ? ' (opcional)' : '' ?></label><input class="form-control mb-3" type="password" name="password"<?= $user ? '' : ' required' ?>><label class="form-label">Grupos</label><?php foreach ($data['groups'] as $item): ?><label class="form-check"><input class="form-check-input" type="checkbox" name="groups[]" value="<?= (int) $item->id ?>"<?= in_array((string) $item->id, $data['selectedUserGroups'], true) ? ' checked' : '' ?>> <?= htmlspecialchars((string) $item->name, ENT_QUOTES, 'UTF-8') ?></label><?php endforeach; ?><button class="btn btn-primary mt-3" type="submit">Guardar utilizador</button></form></div></article></div>
    </div>
    <div class="mt-4"><article class="card"><div class="card-header">Utilizadores</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Nome</th><th>E-mail</th><th></th></tr></thead><tbody><?php foreach ($data['users'] as $item): ?><tr><td><?= htmlspecialchars((string) $item->nome, ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) $item->email, ENT_QUOTES, 'UTF-8') ?></td><td><a href="index.php?class=AccessManagement&amp;method=onUsers&amp;user_id=<?= (int) $item->id ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table></div></article></div>
    <?php else: ?>
    <div class="row g-4"><div class="col-12 col-xl-7"><article class="card"><div class="card-header"><?= $section === 'groups' ? 'Novo grupo' : 'Permissões do grupo' ?></div><div class="card-body"><form method="post" action="index.php?class=AccessManagement&amp;method=onSaveGroup"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($data['csrf'], ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) ($group->id ?? 0) ?>"><label class="form-label">Nome</label><input class="form-control mb-3" name="name" required value="<?= htmlspecialchars((string) ($group->name ?? ''), ENT_QUOTES, 'UTF-8') ?>"><label class="form-label">Descrição</label><input class="form-control mb-3" name="description" value="<?= htmlspecialchars((string) ($group->description ?? ''), ENT_QUOTES, 'UTF-8') ?>"><?php if ($section === 'permissions'): ?><label class="form-label">Permissões</label><div class="access-permissions"><?php foreach ($data['permissions'] as $value => $label): ?><label class="form-check"><input class="form-check-input" type="checkbox" name="permissions[]" value="<?= htmlspecialchars($value, ENT_QUOTES, 'UTF-8') ?>"<?= in_array($value, $data['selectedGroupPermissions'], true) ? ' checked' : '' ?>> <?= htmlspecialchars($label, ENT_QUOTES, 'UTF-8') ?></label><?php endforeach; ?></div><?php else: ?><input type="hidden" name="permissions[]" value=""><?php endif; ?><button class="btn btn-primary mt-3" type="submit">Guardar grupo</button></form></div></article></div><div class="col-12 col-xl-5"><article class="card"><div class="card-header">Grupos</div><div class="table-responsive"><table class="table mb-0"><tbody><?php foreach ($data['groups'] as $item): ?><tr><td><?= htmlspecialchars((string) $item->name, ENT_QUOTES, 'UTF-8') ?></td><td><a href="index.php?class=AccessManagement&amp;method=on<?= $section === 'groups' ? 'Groups' : 'Permissions' ?>&amp;group_id=<?= (int) $item->id ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table></div></article></div></div>
